// org.client.create — E1 AC1 (top of the SOP-DEL-02 §3 hierarchy). Generated by `pnpm gen:command`;
// guard cases kept, acceptance cases added (04-testing §1).
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, countRows, createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  Conflict,
  Forbidden,
  openTestKernel,
  ValidationFailed,
  type TestKernel,
} from '../../kernel/index.ts';
import { createClient } from '../commands/create-client.ts';

const director = aStaffActor({ roles: ['director'] });
const other = aStaffActor();
const audited = async () => countRows(testDb.url, 'audit_event WHERE command = $1', [createClient.name]);
const clients = async () => countRows(testDb.url, 'client');
let testDb: TestDatabase;
let t: TestKernel;

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url);
  t.grant(director, createClient.permission);
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('org.client.create', () => {
  it('refuses an actor without the permission and records nothing', async () => {
    const attempt = t.kernel.execute(createClient, other, { shortCode: 'CLIENTA', name: 'Client A' }, 'test');
    await expect(attempt).rejects.toBeInstanceOf(Forbidden);
    expect([await clients(), await audited()]).toEqual([0, 0]);
  });

  it('refuses a client without a name', async () => {
    const attempt = t.kernel.execute(createClient, director, { shortCode: 'CLIENTA', name: ' ' }, 'test');
    await expect(attempt).rejects.toBeInstanceOf(ValidationFailed);
  });

  it('creates the client with its short code in capitals, audited, with an event for other modules', async () => {
    const created = await t.kernel.execute(
      createClient,
      director,
      { shortCode: 'clienta', name: 'Client A' },
      'test',
    );
    expect(created).toMatchObject({ shortCode: 'CLIENTA', name: 'Client A' });
    expect(
      await countRows(testDb.url, 'client WHERE id = $1 AND short_code = $2', [created.id, 'CLIENTA']),
    ).toBe(1);
    expect(
      await countRows(testDb.url, 'audit_event WHERE command = $1 AND client_id = $2', [
        createClient.name,
        created.id,
      ]),
    ).toBe(1);
    expect(await countRows(testDb.url, `outbox WHERE event_type = 'org.client.created'`)).toBe(1);
  });

  it('refuses a short code that is not 1–8 letters, citing SOP-DEL-02 §3', async () => {
    const attempt = t.kernel.execute(
      createClient,
      director,
      { shortCode: 'CLIENTABC', name: 'Client B' },
      'test',
    );
    await expect(attempt).rejects.toMatchObject({ code: 'rule_violation', clause: 'SOP-DEL-02 §3' });
    expect(await clients()).toBe(1);
  });

  it('refuses a short code another client already has', async () => {
    const attempt = t.kernel.execute(
      createClient,
      director,
      { shortCode: 'ClientA', name: 'Client A2' },
      'test',
    );
    await expect(attempt).rejects.toBeInstanceOf(Conflict);
    expect(await clients()).toBe(1);
  });
});
